    PATH_CLS = CloudURLInfo
    REQUIRES = {"webhdfs": "webhdfs"}
    PARAM_CHECKSUM = "etag"
    COPY_POLL_SECONDS = 5
    LIST_OBJECT_PAGE_SIZE = 100

    def __init__(self, url=None, config=None):
        super().__init__(url, config)
        self.path_info = self.PATH_CLS(url) if url else None
        self.endpoint = config.get("webhdfs_endpoint") or os.getenv("WEBHDFS_ENDPOINT")

        self.key_id = (
            config.get("webhdfs_key_id")
            or os.getenv("WEBHDFS_ACCESS_KEY_ID")
            or "defaultId"
        )
        self.key_secret = (
            config.get("webhdfs_key_secret")
            or os.getenv("WEBHDFS_ACCESS_KEY_SECRET")
            or "defaultSecret"
        )

    @wrap_prop(threading.Lock())
    @cached_property
    def webhdfs_service(self):
        import webhdfs

        logger.debug(f"URL: {self.path_info}")
        logger.debug(f"key id: {self.key_id}")
        logger.debug(f"key secret: {self.key_secret}")

        auth = webhdfs.Auth(self.key_id, self.key_secret)
        bucket = webhdfs.Bucket(auth, self.endpoint, self.path_info.bucket)
        return bucket

    def _generate_download_url(self, path_info, expires=3600):
        assert path_info.bucket == self.path_info.bucket

        return self.webhdfs_service.sign_url("GET", path_info.path, expires)

    def _list_paths(self, path_info):
        import webhdfs

        for blob in webhdfs.ObjectIterator(
            self.webhdfs_service, prefix=path_info.path
        ):
            yield blob.key

    def walk_files(self, path_info, **kwargs):
        if not kwargs.pop("prefix", False):
            path_info = path_info / ""
        for fname in self._list_paths(path_info):
            if fname.endswith("/"):
                continue
            yield path_info.replace(path=fname)

    def exists(self, path_info):
        paths = self._list_paths(path_info)
        return any(path_info.path == path for path in paths)

    def remove(self, path_info):
